/*
 * A188376  Positions of 1 in A188374; complement of A188375.
 * https://oeis.org/A188376
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = 2*floor(n/√2) + n. The difference sequence d(n) =
 *            a(n+1)-a(n) is the Pell word generated by the morphism 3 → 331,
 *            1 → 3. The implementation builds this word up to length n‑1 and
 *            sums its first n‑1 terms to obtain a(n)
 * Range:     u8 n <= 106, u16 n <= 2000, u32 n <= 2000, u64 n <= 2000,
 *            u128 n <= 2000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>

seq_t a(idx_t n)
{
    /* Handle the trivial case directly. */
    if (n == 1) {
        return (seq_t)1;
    }

    /* We need the first n-1 elements of the Pell word. */
    const size_t target = (size_t)(n - 1);          /* target length of d(·)   */
    unsigned char *cur  = (unsigned char *)malloc(sizeof(unsigned char) * target);
    unsigned char *nxt  = (unsigned char *)malloc(sizeof(unsigned char) * target);
    if (!cur || !nxt) { /* in the unlikely event of an allocation failure */
        if (cur) free(cur);
        if (nxt) free(nxt);
        return (seq_t)0; /* fallback */
    }

    /* Initial word: single symbol '3' (not actually stored as int 3). */
    cur[0] = 3;
    size_t cur_len = 1;

    /* Expand the word until we have at least 'target' elements. */
    while (cur_len < target) {
        size_t nxt_len = 0;
        for (size_t i = 0; i < cur_len && nxt_len < target; ++i) {
            if (cur[i] == 3) {
                if (nxt_len < target) nxt[nxt_len++] = 3;
                if (nxt_len < target) nxt[nxt_len++] = 3;
                if (nxt_len < target) nxt[nxt_len++] = 1;
            } else { /* cur[i] == 1 */
                if (nxt_len < target) nxt[nxt_len++] = 3;
            }
        }
        /* Prepare for the next iteration. */
        unsigned char *tmp = cur;
        cur = nxt;
        nxt = tmp;
        cur_len = nxt_len;
    }

    /* Compute the sum of the first 'target' terms of the Pell word. */
    seq_t sum = (seq_t)0;
    for (size_t i = 0; i < target; ++i) {
        sum += (cur[i] == 3) ? (seq_t)3 : (seq_t)1;
    }

    free(cur);  /* 'cur' and 'nxt' point to the same block; free once. */

    /* a(n) = 1 + sum of first n-1 differences.   */
    return (seq_t)1 + sum;
}
